// Original DiceController curves, rotation correction and Dice_44001 model.
export const mulQ=(a,b)=>({x:a.w*b.x+a.x*b.w+a.y*b.z-a.z*b.y,y:a.w*b.y-a.x*b.z+a.y*b.w+a.z*b.x,z:a.w*b.z+a.x*b.y-a.y*b.x+a.z*b.w,w:a.w*b.w-a.x*b.x-a.y*b.y-a.z*b.z});
export function eulerQ(e){const q=(axis,v)=>{const h=v*Math.PI/360;return {x:axis===0?Math.sin(h):0,y:axis===1?Math.sin(h):0,z:axis===2?Math.sin(h):0,w:Math.cos(h)};};return mulQ(mulQ(q(1,e.y),q(0,e.x)),q(2,e.z));}
export function sampleCurve(keys,time,quaternion=false){let a=keys[0],b=a;for(let i=1;i<keys.length;i++){b=keys[i];if(time<=b.time)break;a=b;}if(time>=keys.at(-1).time)return {...keys.at(-1).value};const dt=b.time-a.time;if(dt<=0)return {...a.value};const t=Math.max(0,Math.min(1,(time-a.time)/dt)),t2=t*t,t3=t2*t,result={};for(const k of Object.keys(a.value))result[k]=(2*t3-3*t2+1)*a.value[k]+(t3-2*t2+t)*dt*(a.outSlope?.[k]||0)+(-2*t3+3*t2)*b.value[k]+(t3-t2)*dt*(b.inSlope?.[k]||0);if(quaternion){const n=Math.hypot(result.x,result.y,result.z,result.w);for(const k of Object.keys(result))result[k]/=n||1;}return result;}
export function rotationMatrix(q,scale=1){const {x,y,z,w}=q;return [(1-2*y*y-2*z*z)*scale,(2*x*y+2*w*z)*scale,(2*x*z-2*w*y)*scale,0,(2*x*y-2*w*z)*scale,(1-2*x*x-2*z*z)*scale,(2*y*z+2*w*x)*scale,0,(2*x*z+2*w*y)*scale,(2*y*z-2*w*x)*scale,(1-2*x*x-2*y*y)*scale,0,0,0,0,1];}
export class OriginalDice {
 constructor(scene,game){this.scene=scene;this.canvas=document.createElement('canvas');this.canvas.id='dice-world';this.canvas.width=750;this.canvas.height=1624;this.canvas.style.cssText='position:absolute;inset:0;width:750px;height:1624px;z-index:4;pointer-events:none';game.append(this.canvas);this.ctx=this.canvas.getContext('2d');this.canvas.hidden=true;}
 async load(){this.data=await fetch('assets/scene/dice-prop.json').then(r=>r.json());for(const o of this.data.objects)this.scene.meshes[o.mesh.name]=o.mesh;for(const t of this.data.textures){const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=t.url;});this.scene.images[t.url]=image;}}
 frames(values,origin,time,clipIndex=1){const clip=this.data.clips[clipIndex],rootScale=this.data.controller.parents.Dice1.parentChain[0].scale.x;return values.map((value,index)=>{const track=clip.tracks['Dice'+(index+1)],position=sampleCurve(track.position,time),parent=sampleCurve(track.rotation,time,true),correction=eulerQ(this.data.controller.correctionEulers[clip.authoredLandingFaces[index]-1][value-1]);return {position:{x:origin.x+position.x*rootScale,y:origin.y+position.y*rootScale,z:origin.z+position.z*rootScale},quaternion:mulQ(parent,correction),scale:rootScale*this.data.objects[0].local.scale.x,value};});}
 drawShadow(mesh,matrix,position,material){const off=material.colors._ShadowOffset,points=[];for(let i=0;i<mesh.positions.length;i+=3){const [x,y,z]=mesh.positions.slice(i,i+3),wx=matrix[0]*x+matrix[4]*y+matrix[8]*z,wy=matrix[1]*x+matrix[5]*y+matrix[9]*z,wz=matrix[2]*x+matrix[6]*y+matrix[10]*z;points.push(this.scene.project(position.x+wx+off.r*wy+off.b,position.y+material.floats._ShadowHeight,position.z+wz+off.g*wy+off.a));}const x=Math.floor(Math.min(...points.map(p=>p.x)))-1,y=Math.floor(Math.min(...points.map(p=>p.y)))-1,w=Math.ceil(Math.max(...points.map(p=>p.x))-x)+1,h=Math.ceil(Math.max(...points.map(p=>p.y))-y)+1;const canvas=document.createElement('canvas');canvas.width=w*2;canvas.height=h*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.fillStyle='black';for(let i=0;i<mesh.indices.length;i+=3){ctx.beginPath();mesh.indices.slice(i,i+3).forEach((id,n)=>{const p=points[id];n?ctx.lineTo(p.x-x,p.y-y):ctx.moveTo(p.x-x,p.y-y);});ctx.closePath();ctx.fill();}this.ctx.save();this.ctx.globalAlpha=material.colors._ShadowColor.a;this.ctx.drawImage(canvas,x,y,w,h);this.ctx.restore();}
 redraw(){if(!this.canvas.hidden&&this.lastDisplay)this.render(...this.lastDisplay);}
 render(values,origin,time){this.lastDisplay=[values,origin,time];this.ctx.clearRect(0,0,750,1624);const frames=this.frames(values,origin,time);this.lastFrames=frames;for(const f of frames){const object=this.data.objects[0],matrix=rotationMatrix(f.quaternion,f.scale),sprite=this.scene.tileSprite(object.mesh.name,0,matrix,object.materials[0].texture.url,'dice'),p=this.scene.project(f.position.x,f.position.y,f.position.z);this.drawShadow(object.mesh,matrix,f.position,object.materials.find(x=>x.isShadow));this.ctx.drawImage(sprite.canvas,p.x+sprite.x,p.y+sprite.y,sprite.width,sprite.height);}}
 async play(values){const slot=((this.scene.position+1+Math.floor(Math.random()*2))%40)+1;const p=this.scene.hooks.slots[String(slot)].dicePositions[0].positionInNormalPrefab,origin={x:p.x*.9,y:p.y*.9,z:p.z*.9};const clip=this.data.clips[1],start=performance.now();this.canvas.hidden=false;this.playing=true;await new Promise(resolve=>{const tick=()=>{const t=Math.min(clip.duration,(performance.now()-start)/1000*clip.speed);this.render(values,origin,t);if(t<clip.duration)requestAnimationFrame(tick);else resolve();};tick();});await new Promise(r=>setTimeout(r,250));this.playing=false;}
 clear(){this.canvas.hidden=true;this.ctx.clearRect(0,0,750,1624);}
}
